/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import insertDimension = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	insertDimension( x, 1, false ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is not provided a first argument which is an ndarray...
{
	insertDimension( '5', 1, false ); // $ExpectError
	insertDimension( 5, 1, false ); // $ExpectError
	insertDimension( true, 1, false ); // $ExpectError
	insertDimension( false, 1, false ); // $ExpectError
	insertDimension( void 0, 1, false ); // $ExpectError
	insertDimension( null, 1, false ); // $ExpectError
	insertDimension( {}, 1, false ); // $ExpectError
	insertDimension( [ '5' ], 1, false ); // $ExpectError
	insertDimension( ( x: number ): number => x, 1, false ); // $ExpectError
}

// The compiler throws an error if the function is not provided a second argument which is a number...
{
	const x = zeros( [ 2, 2 ] );

	insertDimension( x, '5', false ); // $ExpectError
	insertDimension( x, true, false ); // $ExpectError
	insertDimension( x, false, false ); // $ExpectError
	insertDimension( x, void 0, false ); // $ExpectError
	insertDimension( x, null, false ); // $ExpectError
	insertDimension( x, {}, false ); // $ExpectError
	insertDimension( x, [ '5' ], false ); // $ExpectError
	insertDimension( x, ( x: number ): number => x, false ); // $ExpectError
}

// The compiler throws an error if the function is not provided a third argument which is a boolean...
{
	const x = zeros( [ 2, 2 ] );

	insertDimension( x, 1, '5' ); // $ExpectError
	insertDimension( x, 1, 5 ); // $ExpectError
	insertDimension( x, 1, void 0 ); // $ExpectError
	insertDimension( x, 1, null ); // $ExpectError
	insertDimension( x, 1, {} ); // $ExpectError
	insertDimension( x, 1, [ '5' ] ); // $ExpectError
	insertDimension( x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ] );

	insertDimension(); // $ExpectError
	insertDimension( x ); // $ExpectError
	insertDimension( x, 1 ); // $ExpectError
	insertDimension( x, 1, false, [ 1, 2, 3 ] ); // $ExpectError
}
